from dataclasses import dataclass
from datetime import datetime, timezone
import math


def utc(dt):
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


@dataclass(frozen=True)
class Event:
    source: str
    series: str
    valid_at: datetime
    available_at: datetime
    value: float
    unit: str = ""
    run_at: datetime | None = None
    lead_minutes: int | None = None

    def __post_init__(self):
        object.__setattr__(self, "valid_at", utc(self.valid_at))
        object.__setattr__(self, "available_at", utc(self.available_at))
        if self.run_at is not None:
            object.__setattr__(self, "run_at", utc(self.run_at))


class EventStore:
    """Append-only event store with separate publication and validity clocks."""

    def __init__(self):
        self._events = []

    def append(self, event):
        self._events.append(event)

    def extend(self, events):
        self._events.extend(events)

    def as_of(self, decision_time, source=None, series=None,
              valid_at_lte=None, valid_at_gte=None):
        t = utc(decision_time)
        hi = utc(valid_at_lte) if valid_at_lte is not None else None
        lo = utc(valid_at_gte) if valid_at_gte is not None else None
        out = []
        for event in self._events:
            if event.available_at > t:
                continue
            if source is not None and event.source != source:
                continue
            if series is not None and event.series != series:
                continue
            if hi is not None and event.valid_at > hi:
                continue
            if lo is not None and event.valid_at < lo:
                continue
            out.append(event)
        out.sort(key=lambda e: (e.valid_at, e.available_at))
        return out

    def latest(self, decision_time, source=None, series=None):
        values = self.as_of(decision_time, source=source, series=series)
        return values[-1] if values else None

    def latest_observed(self, decision_time, source=None, series=None):
        """Latest value that was both published and valid by decision_time."""
        values = self.as_of(
            decision_time, source=source, series=series,
            valid_at_lte=decision_time,
        )
        return values[-1] if values else None

    def future_available(self, decision_time, source=None, series=None):
        """Forecast/future-valid values already published by decision_time."""
        return self.as_of(
            decision_time, source=source, series=series,
            valid_at_gte=decision_time,
        )

    def clear_source(self, source):
        self._events = [e for e in self._events if e.source != source]

    def __len__(self):
        return len(self._events)


def power_mean(values, p):
    values = [max(float(v), 1e-9) for v in values]
    if not values:
        raise ValueError("power_mean requires at least one value")
    n = float(len(values))
    if abs(p) < 1e-12:
        return math.exp(sum(math.log(v) for v in values) / n)
    if p < 0 and any(v <= 0 for v in values):
        raise ValueError("negative p requires positive values")
    return (sum(v ** p for v in values) / n) ** (1.0 / p)


class VirtualBattery:
    """Small non-grid-impacting battery used purely as an action surface."""

    def __init__(self, capacity_kwh=20.0, max_kw=5.0, soc_kwh=10.0,
                 eta_charge=0.95, eta_discharge=0.95):
        self.capacity_kwh = float(capacity_kwh)
        self.max_kw = float(max_kw)
        self.soc_kwh = float(soc_kwh)
        self.eta_charge = float(eta_charge)
        self.eta_discharge = float(eta_discharge)

    def clone(self):
        return VirtualBattery(
            self.capacity_kwh,
            self.max_kw,
            self.soc_kwh,
            self.eta_charge,
            self.eta_discharge,
        )

    def step(self, action_kw, price_eur_mwh, dt_hours=0.25):
        action_kw = max(-self.max_kw, min(self.max_kw, float(action_kw)))
        old_soc = self.soc_kwh
        if action_kw >= 0:
            delta = action_kw * dt_hours * self.eta_charge
        else:
            delta = action_kw * dt_hours / self.eta_discharge
        requested_soc = old_soc + delta
        self.soc_kwh = max(0.0, min(self.capacity_kwh, requested_soc))
        grid_energy_mwh = action_kw * dt_hours / 1000.0
        cash_cost = grid_energy_mwh * float(price_eur_mwh)
        violation = abs(requested_soc - self.soc_kwh)
        return cash_cost, violation

