      const existingHash = existingText == null ? null : hashText(existingText);
      if (force || (existingHash != null && existingHash === oldHash)) {
        current.delete(path);
        deleted++;
      } else if (existing != null) {
        conflicts.push(path + ' (upstream deleted)');
      }
    }

    const active = current.has(project.activeFile) ? project.activeFile : bundle.entry;
    const nextProject = {
      activeFile: active,
      entry: bundle.entry,
      files: [...current.entries()]
    };
    localStorage.setItem(PROJECT_KEY, JSON.stringify(nextProject));
    localStorage.setItem(BASELINE_KEY, JSON.stringify({
      channel: bundle.channel || '',
      version: bundle.version || '',
      hashes: incomingHashes
    }));
    localStorage.setItem(PACKAGES_KEY, JSON.stringify(Array.isArray(bundle.packages) ? bundle.packages : []));

    return { updated, deleted, conflicts };
  }

  async function fetchText(url) {
    const response = await fetch(url, { cache: 'no-store' });
    if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
    return response.text();
  }

  async function fetchRemoteBundle() {
    const manifestUrl = new URL(window.POARI_UPDATE_MANIFEST_URL || '../dvx-project.json', document.baseURI);
    const response = await fetch(manifestUrl, { cache: 'no-store' });
    if (!response.ok) throw new Error(`manifest HTTP ${response.status}`);
    const manifest = await response.json();
    if (manifest.schema !== 'poari-dvx-project-v1') throw new Error('Unsupported project manifest.');
    const base = new URL('./', manifestUrl);
    const files = {};
    await Promise.all((manifest.files || []).map(async path => {
      const url = new URL(path, base);
      url.searchParams.set('_dvx', String(Date.now()));
      files[path] = await fetchText(url);
    }));
    return validateBundle({
      schema: 'poari-dvx-update-v1',
      channel: manifest.channel || '',
      version: response.headers.get('etag') || new Date().toISOString(),
      entry: manifest.entry || 'main.py',
      packages: manifest.packages || [],
      files
    });
  }

  function seedEmbedded() {
    const bundle = window.POARI_EMBEDDED_BUNDLE;
    if (!bundle) return;
    let hasProject = false;
    try {
      const project = JSON.parse(localStorage.getItem(PROJECT_KEY) || 'null');
      hasProject = !!(project && Array.isArray(project.files) && project.files.length);
    } catch (_) {}
    if (!hasProject) applyBundle(bundle, { force: true });
    try {
      window.DVX_EDITOR_PACKAGES = JSON.parse(localStorage.getItem(PACKAGES_KEY) || '[]');
    } catch (_) {
      window.DVX_EDITOR_PACKAGES = [];
    }
  }

  function flash(message) {
    try { localStorage.setItem(FLASH_KEY, message); } catch (_) {}
  }

  function showFlash() {
    const status = document.getElementById('status');
    if (!status) return;
    let message = '';
    try {
      message = localStorage.getItem(FLASH_KEY) || '';
      localStorage.removeItem(FLASH_KEY);
    } catch (_) {}
    if (message) status.textContent = message;
  }

  function loadUpdateFile(file) {
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const result = applyBundle(JSON.parse(String(reader.result || '')));
        flash(`updated ${result.updated}, kept ${result.conflicts.length} local`);
        location.reload();
      } catch (err) {
        alert('POARI update failed: ' + (err?.message || err));
      }
    };
    reader.readAsText(file);
  }

  function attachUi() {
    const button = document.getElementById('poariQuickUpdate');
    const picker = document.getElementById('poariUpdateFile');
    const status = document.getElementById('status');
    if (!button || !picker) return;
    button.addEventListener('click', async () => {
      button.disabled = true;
      if (status) status.textContent = 'checking update…';
      try {
        const bundle = await fetchRemoteBundle();
        const result = applyBundle(bundle);
        flash(`updated ${result.updated}, kept ${result.conflicts.length} local`);
        location.reload();
      } catch (err) {
        if (status) status.textContent = 'pick update file';
        picker.value = '';
        picker.click();
      } finally {
        button.disabled = false;
      }
    });
    picker.addEventListener('change', () => {
      const file = picker.files && picker.files[0];
      if (file) loadUpdateFile(file);
    });
    showFlash();
  }

  seedEmbedded();
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', attachUi, { once: true });
  else attachUi();

  window.POARIQuickUpdate = Object.freeze({ applyBundle, fetchRemoteBundle, hashText });
})();

import unittest
from datetime import datetime, timezone

from poari_live.sources import (
    GERMANY_WEATHER_POINTS,
    OpenMeteoForecastClient,
    OpenMeteoRunClient,
    SMARDClient,
)


class SourceContractTests(unittest.TestCase):
    def test_smard_url_contract(self):
        url = SMARDClient.series_url(4359, 1700000000000, region="DE")
        self.assertIn("/4359/DE/4359_DE_quarterhour_1700000000000.json", url)

    def test_smard_payload_becomes_asof_events(self):
        payload = {
            "meta_data": {"created": 1700003600000},
            "series": [[1700000000000, 123.5], [1700000900000, None]],
        }
        client = SMARDClient(lambda url: payload)
        events = client.events("residual_load", 1700000000000, unit="MWh")
        self.assertEqual(len(events), 1)
        self.assertEqual(events[0].value, 123.5)
        self.assertGreaterEqual(events[0].available_at, events[0].valid_at)

    def test_open_meteo_run_preserves_run_and_lead(self):
        payload = {
            "hourly": {
                "time": ["2026-09-16T06:00", "2026-09-16T07:00"],
                "wind_speed_100m": [8.0, 9.0],
            },
            "hourly_units": {"wind_speed_100m": "km/h"},
        }
        client = OpenMeteoRunClient(lambda url: payload)
        run = datetime(2026, 9, 16, 6, 0, tzinfo=timezone.utc)
        events = client.events(52.5, 13.4, run, ["wind_speed_100m"])
        self.assertEqual([e.lead_minutes for e in events], [0, 60])
        self.assertEqual(events[0].run_at, run)
        self.assertEqual(events[0].available_at.hour, 9)

    def test_everyday_weather_field_keeps_spatial_and_directional_information(self):
        self.assertGreaterEqual(len(GERMANY_WEATHER_POINTS), 8)
        url = OpenMeteoForecastClient.url(52.5, 13.4, forecast_hours=12)
        self.assertIn("wind_speed_100m", url)
        self.assertIn("wind_direction_100m", url)
        self.assertIn("shortwave_radiation", url)


if __name__ == "__main__":
    unittest.main()
